def list_rules(country_code="IN", area=None, applicability_status=None, source_verification_status=None, subdivision_code=None):
    items = [dict(item) for item in RULES if item["country_code"] == country_code.upper() and (subdivision_code is None or item["subdivision_code"] in (None, subdivision_code.upper()))]
    if area:
        items = [item for item in items if item["area"] == area]
    if applicability_status:
        items = [item for item in items if item["applicability_status"] == applicability_status]
    if source_verification_status:
        items = [item for item in items if item["source_verification_status"] == source_verification_status]
    return items

def get_rule(rule_id, country_code="IN", subdivision_code=None):
    for item in RULES:
        if item["id"] == rule_id and item["country_code"] == country_code.upper() and (subdivision_code is None or item["subdivision_code"] in (None, subdivision_code.upper())):
            return dict(item)
    return None
